      name: 'client_put',
      description: 'Store a value for a key under the given client',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Non-empty client identifier' },
          key: { type: 'string', description: 'Non-empty key' },
          value: { type: 'string', description: 'Non-empty value' }
        },
        required: ['client_id', 'key', 'value'],
        additionalProperties: false
      }
    },
    {
      name: 'client_get',
      description: 'Retrieve a value for a key under the given client',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Non-empty client identifier' },
          key: { type: 'string', description: 'Non-empty key' }
        },
        required: ['client_id', 'key'],
        additionalProperties: false
      }
    }
  ];
}

function assertNonEmptyString(value, name) {
  if (typeof value !== 'string' || value.length === 0) {
    const err = new Error(`${name} must be a non-empty string`);
    err.code = -32602;
    throw err;
