}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'open_client': {
      assertNonEmptyString(args.client_id, 'client_id');
      if (!clients.has(args.client_id)) {
        clients.set(args.client_id, new Map());
      }
      return { content: [{ type: 'text', text: `client ${args.client_id} opened` }] };
    }
    case 'client_put': {
      assertNonEmptyString(args.client_id, 'client_id');
      assertNonEmptyString(args.key, 'key');
      assertNonEmptyString(args.value, 'value');
      const store = clients.get(args.client_id);
      if (!store) {
        const err = new Error(`unknown client: ${args.client_id}`);
        err.code = -32602;
        throw err;
      }
      store.set(args.key, args.value);
      return { content: [{ type: 'text', text: `stored ${args.key}` }] };
    }
    case 'client_get': {
      assertNonEmptyString(args.client_id, 'client_id');
      assertNonEmptyString(args.key, 'key');
      const store = clients.get(args.client_id);
      if (!store) {
        const err = new Error(`unknown client: ${args.client_id}`);
